"use client"

import animation from "react-useanimations/lib/gift"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Gift" from https://useanimations.com (MIT): https://useanimations.com/icons/gift
export function AnimatedGift(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}
